import json

r0 = list(map(int, "7 7 7 3 3 7 3 7 7 7 7 7 7 7 7 7 3 7 7 7 7 7 7 7 3 7".split()))
r1 = list(map(int, "7 3 7 7 3 7 7 7 7 7 7 7 7 7 7 3 3 3 7 7 3 3 3 7 7 3".split()))

def expand_3s_in_row(row):
    result = list(row)
    expanded = set()

    for i, val in enumerate(row):
        if val == 3:
            expanded.add(i)
            if i-1 >= 0: expanded.add(i-1)
            if i+1 < len(row): expanded.add(i+1)

    new_expanded = set(expanded)
    for e in expanded:
        if e-1 >= 0 and e-1 not in new_expanded: new_expanded.add(e-1)
        if e+1 < len(row) and e+1 not in new_expanded: new_expanded.add(e+1)

    return [3 if i in new_expanded else 7 for i in range(len(result))]

output_r0 = expand_3s_in_row(r0)
output_r1 = expand_3s_in_row(r1)

final_output = [output_r0, output_r1]
print(json.dumps({"action": "submit", "grid": final_output}))

