def orthogonal_has_3(r, c):
    """Check if current cell or its 4 orthogonal neighbors contain a 3"""
    result = [(r, c)]
    for nr, nc in [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]:
        if 0 <= nr < 2 and 0 <= nc < 26:
            result.append((nr, nc))

    return any(grid[nr][nc] == 3 for nr, nc in result)

